/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="services-band"]{padding-top:120px;padding-bottom:120px}
@media (max-width: 640px){
[data-bz-node="services-band"]{padding-top:64px;padding-bottom:64px}
}

/* --------------------------------------------------------------- SERVICES ---
   Rows are separated by a top rule and the list is closed by one more, so the
   set reads as a table rather than as seven cards. */

[data-bz-node="services-band"] .bz-block { padding-block: 0; }
[data-bz-node="services-heading"] h2 { margin: 0 0 20px; }
[data-bz-node="services-lede"] { margin-bottom: 56px; }
[data-bz-node="services-lede"] .bz-text { max-width: 680px; }
[data-bz-node="services-lede"] p { line-height: 1.7; }

[data-bz-node="services-list-col"] > .bz-row {
  display: grid;
  grid-template-columns: 60px 1fr auto;
  gap: 28px;
  align-items: center;
  border-top: 1px solid var(--line);
  padding: 32px 0;
}
[data-bz-node="services-list-col"] > .bz-row:last-child {
  border-bottom: 1px solid var(--line);
}

[data-bz-node="services-list-col"] > .bz-row > .bz-col:nth-child(1) .bz-block--text p {
  font: 800 20px / 1.6 var(--font-heading);
  color: var(--muted);
  margin: 0;
}
[data-bz-node="services-list-col"] .bz-block--heading h3 {
  font: 700 20px / 1.6 var(--font-heading);
  margin: 0 0 4px;
}
[data-bz-node="services-list-col"] > .bz-row > .bz-col:nth-child(2) .bz-block--text p {
  font-size: var(--text-base, 15px);
  line-height: 1.6;
  color: #3f3f3f;
  margin: 0;
}
[data-bz-node="services-list-col"] .bz-block--text .bz-text { max-width: none; }
[data-bz-node="services-list-col"] .bz-block--buttons .bz-btn {
  padding: 4px 0;
  font: 700 var(--text-small) / 1.6 var(--font-body);
  text-decoration: none;
  white-space: nowrap;
}
[data-bz-node="services-list-col"] .bz-block--buttons .bz-btns { justify-content: flex-end; }

@media (max-width: 640px) {
  [data-bz-node="services-list-col"] > .bz-row {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 24px 0;
  }
  [data-bz-node="services-list-col"] > .bz-row > .bz-col:nth-child(1) .bz-block--text p { font-size: 16px; }
}
